VERB_HINT_ROWS5.split('\n').forEach(row=>{const [word,ar,en]=row.split('|');if(!PRON_HINTS5[word])PRON_HINTS5[word]=[ar,en,''];});
function pronunciationHint5(text){const exact=PRON_HINTS5[text]||PRON_HINTS5[text.toLowerCase()];if(exact)return {ar:exact[0],en:exact[1],ipa:exact[2],complete:true};const tokens=text.match(/[\p{L}]+/gu)||[];const hints=tokens.map(t=>PRON_HINTS5[t]||PRON_HINTS5[t.toLowerCase()]);return {ar:tokens.map((t,i)=>hints[i]?.[0]||'['+t+']').join(' · '),en:tokens.map((t,i)=>hints[i]?.[1]||'['+t+']').join(' · '),ipa:'',complete:hints.length>0&&hints.every(Boolean)};}
function hintsHTML5(text){const h=pronunciationHint5(text);return `<details class="pron-hint5"><summary>مساعدة النطق بالعربي والإنجليزي</summary><p class="subtle">تقريب مساعد، وليس بديلًا للصوت. الإنجليزية هنا تهجئة صوتية تقريبية وليست ترجمة. ${h.complete?'':'الكلمات بين [ ] لم نضف لها تهجئة مساعدة بعد؛ استخدم زر سماعها.'}</p><div dir="rtl" lang="ar">${esc(h.ar)}</div><div dir="ltr" lang="en">${esc(h.en)}</div>${h.ipa?`<div dir="ltr">IPA: /${esc(h.ipa)}/</div>`:''}<small>ڤ = v، پ = p. صوتا ü وö ليسا واوًا، وch الأمامية ليست شينًا أو خاء عربية تمامًا.</small></details>`;}
function sentenceTools5(text){return `${audioButton4(text,'اسمع النص')}<details class="word-sounds5"><summary>اسمع كل كلمة لوحدها</summary><div class="actions" dir="ltr">${(text.match(/[\p{L}]+(?:[-’'][\p{L}]+)*/gu)||[]).map(w=>audioButton4(w,w)).join('')}</div></details>${hintsHTML5(text)}`;}
function constructionHTML5(rows){return rows.map(([rule,pattern,q,a,ar])=>`<article class="construction5"><h4>${esc(rule)}</h4><p class="de pattern5" lang="de">${esc(pattern)}</p><div class="bilingual5"><span>السؤال</span><p class="de" lang="de">${esc(q)}</p>${sentenceTools5(q)}<span>مثال إجابة</span><p class="de" lang="de">${esc(a)}</p><p dir="rtl">${esc(ar)}</p>${sentenceTools5(a)}</div></article>`).join('');}
function topicPrepHTML5(id){const rows=['months','weather','time'].includes(id)?CALENDAR_PREPS5:(TOPIC_PREPS5[id]||[]).flatMap(de=>CONSTRUCTIONS5[de]||[]);return `<section class="panel"><h2>التراكيب وحروف الجر</h2><p>مش كل فعل له حرف جر ثابت. فرّق بين تركيب الفعل، والمكان، والوقت. الحالة هنا تخص المثال المعروض.</p>${constructionHTML5(rows)}<p class="subtle">Akkusativ: حالة المفعول المباشر غالبًا. Dativ: تأتي بعد حروف مثل mit وaus وbei، أو مع أفعال مثل helfen. im = in dem، am = an dem، ins = in das، zum = zu dem.</p></section>`;}
